const eingabe = $input.first().json;
const text = (wert) => (wert === undefined || wert === null ? '' : String(wert));
const aktiv = (wert) => {
  if (wert === undefined || wert === null || wert === '') return true;
  return !(wert === false || wert === 0 || ['false', '0', 'nein', 'no'].includes(String(wert).toLowerCase()));
};
const html = (wert) => text(wert).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const entschaerfen = (wert) => text(wert).replace(/@(channel|all|here)\b/gi, '@​$1');
const einzeilig = (wert, max) => text(wert).replace(/[\r\n]+/g, ' ').replace(/[^\x20-\xFF]/g, '').trim().slice(0, max);

const quelle = text(eingabe.quelle) || 'n8n';
const titel = text(eingabe.titel) || 'Meldung';
const inhalt = text(eingabe.text);
const prioritaet = text(eingabe.prioritaet) || 'default';
const tags = text(eingabe.tags);
const tagListe = tags.split(',').map((tag) => tag.trim()).filter(Boolean);
const thema = text(eingabe.thema).replace(/[^A-Za-z0-9_-]/g, '') || 'Home-Lab-MDM';

let status = text(eingabe.status).toLowerCase();
if (!['success', 'error', 'warning', 'info'].includes(status)) {
  if (tagListe.includes('white_check_mark')) status = 'success';
  else if (tagListe.some((tag) => ['x', 'rotating_light', 'skull', 'boom'].includes(tag))) status = 'error';
  else if (tagListe.includes('warning') || ['high', 'urgent', '4', '5'].includes(prioritaet)) status = 'warning';
  else status = 'info';
}
const STIL = {
  success: { icon: '✅', farbe: '#2e7d32', label: 'Erfolg', tag: 'white_check_mark' },
  error: { icon: '\u{1F6A8}', farbe: '#c62828', label: 'Fehler', tag: 'rotating_light' },
  warning: { icon: '⚠️', farbe: '#ef6c00', label: 'Warnung', tag: 'warning' },
  info: { icon: 'ℹ️', farbe: '#1565c0', label: 'Info', tag: 'information_source' },
}[status];

const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'medium' });

const mmText = text(eingabe.mattermostText) || ('#### ' + STIL.icon + ' ' + titel + '\n_' + quelle + '_\n\n' + inhalt);

const ntfyHeader = { Title: einzeilig(titel, 120) || 'Meldung', Priority: einzeilig(prioritaet, 12), Tags: einzeilig(tags || STIL.tag, 100) };
if (text(eingabe.aktionen)) ntfyHeader.Actions = einzeilig(eingabe.aktionen, 600);
if (text(eingabe.klick)) ntfyHeader.Click = einzeilig(eingabe.klick, 400);
if (text(eingabe.anhang)) ntfyHeader.Attach = einzeilig(eingabe.anhang, 400);

const mailHtml = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px">'
  + '<div style="background:' + STIL.farbe + ';color:#ffffff;padding:12px 16px;border-radius:6px 6px 0 0;font-size:16px"><b>' + STIL.icon + ' ' + STIL.label + '</b> – ' + html(titel) + '</div>'
  + '<div style="border:1px solid #dddddd;border-top:none;padding:16px;border-radius:0 0 6px 6px">'
  + (text(eingabe.mailHtml) ? '<div style="margin:0 0 16px;font-size:14px;line-height:1.5">' + text(eingabe.mailHtml) + '</div>' : '<p style="margin:0 0 16px;font-size:14px;line-height:1.5">' + (html(inhalt).replace(/\n/g, '<br>') || '<i>(kein Text)</i>') + '</p>')
  + '<table style="font-size:12px;color:#666666;border-collapse:collapse">'
  + '<tr><td style="padding:2px 12px 2px 0">Quelle</td><td>' + html(quelle) + '</td></tr>'
  + '<tr><td style="padding:2px 12px 2px 0">Zeit</td><td>' + html(zeit) + '</td></tr>'
  + '<tr><td style="padding:2px 12px 2px 0">ntfy-Thema</td><td>' + html(thema) + '</td></tr>'
  + '</table></div></div>';

return [{
  json: {
    quelle,
    status,
    mm_aktiv: aktiv(eingabe.mattermost),
    mm_channel: text(eingabe.kanal) || 'Berichte',
    mm_channel_id: text(eingabe.kanalId),
    mm_message: entschaerfen(mmText).slice(0, 12000),
    ntfy_aktiv: aktiv(eingabe.ntfy),
    ntfy_url: 'http://ntfy.ntfy.svc.cluster.local/' + thema,
    ntfy_headers: ntfyHeader,
    ntfy_body: (inhalt || titel).slice(0, 3500),
    mail_aktiv: aktiv(eingabe.mail),
    mail_subject: ('[' + STIL.label + '] ' + quelle + ': ' + titel).replace(/[\r\n]+/g, ' ').slice(0, 200),
    mail_html: mailHtml,
    mail_text: titel + '\n\n' + inhalt + '\n\nQuelle: ' + quelle + '\nZeit: ' + zeit,
  },
}];

const meldung = $('Meldung aufbereiten').first().json;
if (meldung.mm_channel_id) {
  return [{ json: { channel_id: meldung.mm_channel_id, message: meldung.mm_message } }];
}
const kanaele = $input.all().map((item) => item.json).filter((kanal) => kanal && kanal.name);
const gesucht = String(meldung.mm_channel).toLowerCase();
const ziel = kanaele.find((kanal) => String(kanal.name).toLowerCase() === gesucht || String(kanal.display_name || '').toLowerCase() === gesucht);
if (!ziel) {
  throw new Error('Kanal "' + meldung.mm_channel + '" nicht gefunden oder n8n-bot ist dort kein Mitglied');
}
return [{ json: { channel_id: ziel.id, message: meldung.mm_message } }];
